```python
import math


def distribute_tokens(total, weights):
    if isinstance(total, bool) or not isinstance(total, int):
        raise TypeError("total must be an integer")
    if total < 0:
        raise ValueError("total must be non-negative")
    if not isinstance(weights, dict):
        raise TypeError("weights must be a dictionary")
    if not weights:
        if total == 0:
            return {}
        raise ValueError("cannot allocate without weights")

    entries = []
    for index, (name, weight) in enumerate(weights.items()):
        if not isinstance(name, str):
            raise TypeError("names must be strings")
        if not name:
            raise ValueError("names must not be empty")
        if isinstance(weight, bool) or not isinstance(weight, (int, float)):
            raise TypeError("weights must be numeric")
        if not math.isfinite(weight) or weight <= 0:
            raise ValueError("weights must be finite and positive")
        entries.append((name, float(weight), index))

    weight_sum = sum(weight for _, weight, _ in entries)
    result = {}
    remainders = []
    assigned = 0
    for name, weight, index in entries:
        exact = total * weight / weight_sum
        base = math.floor(exact)
        result[name] = base
        assigned += base
        remainders.append((exact - base, index, name))

    remainders.sort(reverse=True)
    for _, _, name in remainders[:total - assigned]:
        result[name] += 1
    return result
```

